import{_ as a,c as t,o as i,ag as n}from"./chunks/framework.C86mscM5.js";const p=JSON.parse('{"title":"CSR (Client Side Rendering)","description":"","frontmatter":{},"headers":[],"relativePath":"advance/csr/index.md","filePath":"advance/csr/index.md","lastUpdated":1788092044000}'),r={name:"advance/csr/index.md"};function d(c,e,l,o,s,_){return i(),t("div",null,e[0]||(e[0]=[n('<h1 id="csr-client-side-rendering" tabindex="-1">CSR (Client Side Rendering) <a class="header-anchor" href="#csr-client-side-rendering" aria-label="Permalink to &quot;CSR (Client Side Rendering)&quot;">​</a></h1><blockquote><p>CSR 是 &quot;Client-Side Rendering&quot;（客户端渲染）的缩写。它表示页面是在浏览器中通过 JavaScript 渲染的，数据获取、模板和路由等逻辑都在浏览器端完成，而不是在服务器上。</p><p>在 CSR 中，服务器会向浏览器端发送一个空的 HTML 外壳和一些 JavaScript 脚本，然后由浏览器端从服务器的 API 中拉取数据，并将动态内容渲染到页面中。</p></blockquote><h2 id="csr-加载流程" tabindex="-1">CSR 加载流程 <a class="header-anchor" href="#csr-加载流程" aria-label="Permalink to &quot;CSR 加载流程&quot;">​</a></h2><ol><li>浏览器加载 HTML → 用户看到空白页面</li><li>JavaScript 加载完成 → React 渲染页面内容</li><li>后续页面导航 → SPA 模式，客户端渲染</li></ol>',4)]))}const u=a(r,[["render",d]]);export{p as __pageData,u as default};
